import { z } from 'zod'

// Action keys are admin-managed (see the ActionOption model). Built-in keys use
// the legacy UPPERCASE names; keys generated by the admin panel use lowercase
// slugs. Both must match this pattern.
export const ACTION_KEY_PATTERN = /^[A-Za-z0-9](?:[A-Za-z0-9_-]{0,62}[A-Za-z0-9])?$/

export const ACTION_VERIFICATIONS = [
  'AUTO_PROMPT',
  'USER_CONFIRMED',
  'EMAIL_SUBMITTED',
] as const

export const LINK_CONTENT_TYPES = ['URL', 'TEXT', 'FILE'] as const

// Public page bodies (content.*) edited from the admin content manager.
// Generic settings stay at the 2000-char cap in updateSetting.
export const CONTENT_VALUE_MAX_LENGTH = 5000

/** Minimal shape of a next-intl translator, injectable from server actions. */
export type ValidatorMessages = (
  key: string,
  values?: Record<string, string | number | Date>,
) => string

export function makeHttpUrlSchema(t: ValidatorMessages) {
  return z
    .url({ error: t('invalidUrl') })
    .refine((value) => {
      try {
        const { protocol } = new URL(value)
        return protocol === 'http:' || protocol === 'https:'
      } catch {
        return false
      }
    }, t('onlyHttpHttps'))
}

function makeCoverImageSchema(t: ValidatorMessages) {
  return z
    .string()
    .trim()
    .max(2048)
    .refine(
      (value) =>
        value === '' ||
        /^https?:\/\//.test(value) ||
        /^\/api\/media\/[A-Za-z0-9_-]+$/.test(value),
      t('invalidCoverImage'),
    )
}

export function makeActionSchema(t: ValidatorMessages) {
  return z.object({
    type: z.string().trim().regex(ACTION_KEY_PATTERN, t('invalidActionType')),
    label: z.string().trim().max(120).optional().or(z.literal('')),
    target: z.string().trim().max(2048),
  })
}

export function makeLinkInputSchema(t: ValidatorMessages) {
  const httpUrl = makeHttpUrlSchema(t)
  const coverImageSchema = makeCoverImageSchema(t)
  const actionSchema = makeActionSchema(t)

  return z
    .object({
      title: z.string().trim().min(3, t('titleTooShort')).max(140),
      coverImage: coverImageSchema,
      slug: z
        .string()
        .trim()
        .regex(/^[a-z0-9](?:[a-z0-9-]{1,62}[a-z0-9])?$/, t('invalidSlug'))
        .optional()
        .or(z.literal('')),
      contentType: z.enum(LINK_CONTENT_TYPES),
      targetUrl: z.string().trim().max(2048).optional().or(z.literal('')),
      textContent: z.string().trim().max(20000).optional().or(z.literal('')),
      fileId: z.string().trim().max(64).optional().or(z.literal('')),
      expiresAt: z.string().trim().optional().or(z.literal('')),
      actions: z.array(actionSchema).max(10),
    })
    .superRefine((value, ctx) => {
      if (value.contentType === 'URL') {
        const parsed = httpUrl.safeParse(value.targetUrl)
        if (!parsed.success) {
          ctx.addIssue({
            code: 'custom',
            path: ['targetUrl'],
            message: t('destinationUrlRequired'),
          })
        }
      }

      if (value.contentType === 'FILE') {
        if (!value.fileId || value.fileId.length === 0) {
          ctx.addIssue({
            code: 'custom',
            path: ['fileId'],
            message: t('fileRequired'),
          })
        }
      }

      if (value.expiresAt && Number.isNaN(Date.parse(value.expiresAt))) {
        ctx.addIssue({
          code: 'custom',
          path: ['expiresAt'],
          message: t('invalidDatetime'),
        })
      }
    })
}

export type LinkInput = z.infer<ReturnType<typeof makeLinkInputSchema>>
export type ActionInput = z.infer<ReturnType<typeof makeActionSchema>>

export function makeEmailCaptureSchema(t: ValidatorMessages) {
  return z.object({
    email: z.email({ error: t('invalidEmail') }),
    consent: z.literal(true),
  })
}

export const slugParamSchema = z
  .string()
  .regex(/^[a-z0-9](?:[a-z0-9-]{1,62}[a-z0-9])?$/)

export const HANDLE_PATTERN = /^[a-z0-9](?:[a-z0-9-]{1,62}[a-z0-9])?$/

export function makeProfileInputSchema(t: ValidatorMessages) {
  const httpUrl = makeHttpUrlSchema(t)

  const profileLinkSchema = z.object({
    label: z.string().trim().min(1, t('labelRequired')).max(60),
    url: httpUrl,
  })

  return z.object({
    handle: z
      .string()
      .trim()
      .regex(HANDLE_PATTERN, t('invalidHandle')),
    displayName: z.string().trim().max(80).optional().or(z.literal('')),
    bio: z.string().trim().max(500).optional().or(z.literal('')),
    avatarUrl: z
      .string()
      .trim()
      .max(2048)
      .refine(
        (value) =>
          value === '' ||
          /^https?:\/\//.test(value) ||
          /^\/api\/media\/[A-Za-z0-9_-]+$/.test(value),
        t('invalidCoverImage'),
      )
      .optional()
      .or(z.literal('')),
    links: z.array(profileLinkSchema).max(20),
  })
}

export type ProfileInput = z.infer<ReturnType<typeof makeProfileInputSchema>>

export const ABUSE_REASONS = [
  'SPAM',
  'MALWARE',
  'ILLEGAL',
  'COPYRIGHT',
  'IMPERSONATION',
  'OTHER',
] as const

export function makeAbuseReportSchema(t: ValidatorMessages) {
  return z.object({
    slug: z.string().trim().max(64),
    reason: z.enum(ABUSE_REASONS),
    details: z.string().trim().min(10, t('describeProblem')).max(2000),
    reporterEmail: z.email({ error: t('invalidEmail') }).optional().or(z.literal('')),
  })
}

export type AbuseReportInput = z.infer<ReturnType<typeof makeAbuseReportSchema>>
